-- Fakt kartochkalarining ruscha matni — 1-partiya: uch asosiy ajdod.
--
-- OVOZ SAQLANADI. Kartochkalar BIRINCHI SHAXSDA yozilgan («Men 1336-yilda
-- tug'ilganman») — bu ajdodning suhbatdagi ovozi. Tarjimada ham shu ovoz
-- qoladi, aks holda chatda ajdod birdan uchinchi shaxsda gapira boshlardi.
--
-- FAKT O'ZGARMAYDI. Sana, ism, asar nomi va joy nomi asl matndagidek.
--
-- TEKSHIRUV. Bu tarjima metodist ko'zidan o'tmagan. Ustunni paneldan
-- tahrirlash mumkin; bo'sh qoldirilsa — o'zbekcha asl matn ko'rsatiladi.

UPDATE fact_cards SET topic_ru = 'Рождение', question_ru = 'Когда и где родился Амир Темур?', fact_ru = 'Я родился 9 апреля 1336 года в селении Ходжа Илгар близ Кеша (нынешнего Шахрисабза). Мой отец — Амир Тарагай из беков барласа.' WHERE id = 28;
UPDATE fact_cards SET topic_ru = 'Основание государства', question_ru = 'В каком году Амир Темур основал централизованное государство и какой город сделал столицей?', fact_ru = 'В 1370 году я основал в Мавераннахре централизованное государство. Столицей выбрал Самарканд и стремился превратить его в красивейший город мира.' WHERE id = 29;
UPDATE fact_cards SET topic_ru = 'Титул Сохибкиран', question_ru = 'Что означает титул «Сохибкиран»?', fact_ru = 'Меня называют Сохибкиран — это означает «рождённый при соединении счастливых звёзд» и дано в честь моих побед.' WHERE id = 30;
UPDATE fact_cards SET topic_ru = 'Военные походы', question_ru = 'Какие военные походы совершил Амир Темур?', fact_ru = 'За свою жизнь я совершил множество военных походов: против Тохтамышхана (1391, 1395), в Индию (1398–1399), а в 1402 году в Ангорской битве разбил османского султана Баязида Молниеносного.' WHERE id = 31;
UPDATE fact_cards SET topic_ru = '«Уложение Темура»', question_ru = 'Что за труд «Уложение Темура» и о чём в нём говорится?', fact_ru = 'В труде «Уложение Темура» я изложил правила управления государством. Мой девиз: «Сила — в справедливости».' WHERE id = 32;
UPDATE fact_cards SET topic_ru = 'Созидание', question_ru = 'Какие здания были построены при Амире Темуре в Самарканде и Шахрисабзе?', fact_ru = 'В моё время в Самарканде поднялись соборная мечеть Биби-ханым и мавзолей Гур-Эмир, в Шахрисабзе — Ак-Сарай. Я говорил: «Если сомневаешься в нашем могуществе — взгляни на наши постройки!»' WHERE id = 33;
UPDATE fact_cards SET topic_ru = 'Семья', question_ru = 'Кто был детьми Амира Темура?', fact_ru = 'Мои дети: Джахангир, Умаршайх, Мироншах и Шахрух. Один из любимых внуков — учёный Мирзо Улугбек, он сын Шахруха.' WHERE id = 34;
UPDATE fact_cards SET topic_ru = 'Посольские связи', question_ru = 'Как Амир Темур установил связи с государствами Европы?', fact_ru = 'Я установил посольские связи с государствами Европы: испанский посол Руи Гонсалес де Клавихо гостил при моём дворе, я вёл переписку с королями Франции и Англии.' WHERE id = 35;
UPDATE fact_cards SET topic_ru = 'Торговля по Шёлковому пути', question_ru = 'Как Амир Темур развивал торговлю по Великому шёлковому пути?', fact_ru = 'Я развивал торговлю по Великому шёлковому пути: сделал караванные дороги безопасными, превратил Самарканд в центр мировой торговли.' WHERE id = 36;
UPDATE fact_cards SET topic_ru = 'Кончина', question_ru = 'Когда умер Амир Темур и где он похоронен?', fact_ru = 'Я скончался 18 февраля 1405 года в городе Отрар, в начале похода на Китай. Меня похоронили в самаркандском мавзолее Гур-Эмир.' WHERE id = 37;
UPDATE fact_cards SET topic_ru = 'Мой внук Улугбек', question_ru = 'Кто из внуков Амира Темура стал великим учёным?', fact_ru = 'Мой внук Улугбек — сын моего сына Шахруха — впоследствии стал великим учёным и звездочётом. Он построил в Самарканде знаменитую обсерваторию.' WHERE id = 1519;
UPDATE fact_cards SET topic_ru = 'Ак-Сарай', question_ru = 'Какой знаменитый дворец построил Амир Темур в Шахрисабзе?', fact_ru = 'В родном городе Шахрисабзе я построил огромный дворец Ак-Сарай. Его высокий портал сохранился до наших дней и считается гордостью города.' WHERE id = 1520;
UPDATE fact_cards SET topic_ru = 'Мечеть Биби-ханым', question_ru = 'Как называется огромная соборная мечеть, построенная Амиром Темуром в Самарканде?', fact_ru = 'После индийского похода я построил в Самарканде соборную мечеть Биби-ханым. В своё время это была одна из крупнейших мечетей Востока.' WHERE id = 1521;
UPDATE fact_cards SET topic_ru = 'Мои сады вокруг Самарканда', question_ru = 'Какие сады разбил Амир Темур вокруг Самарканда?', fact_ru = 'Вокруг Самарканда я разбил прекрасные сады: Баги Дилкушо, Баги Бехишт, Баги Шамол и другие. В них я принимал гостей и устраивал празднества.' WHERE id = 1522;
UPDATE fact_cards SET topic_ru = 'Мавзолей Гур-Эмир', question_ru = 'В каком мавзолее похоронен Амир Темур?', fact_ru = 'Я похоронен в самаркандском мавзолее Гур-Эмир. Этот мавзолей изначально был построен для моего любимого внука Мухаммада Султана.' WHERE id = 1523;
UPDATE fact_cards SET topic_ru = 'Мой девиз', question_ru = 'Каков знаменитый девиз Амира Темура?', fact_ru = 'Изречение «Сила — в справедливости» известно как мой девиз. По преданиям, эти слова были начертаны и на моей печати. Я стремился управлять государством по справедливости.' WHERE id = 1524;

UPDATE fact_cards SET topic_ru = 'Рождение', question_ru = 'Когда и где родился Мирзо Улугбек?', fact_ru = 'Я родился 22 марта 1394 года в городе Султания, во время военного похода. Моё настоящее имя — Мухаммад Тарагай. Мой дед — великий Амир Темур, отец — Шахрух Мирза.' WHERE id = 38;
UPDATE fact_cards SET topic_ru = 'Правление', question_ru = 'С какого года и сколько времени Мирзо Улугбек управлял Мавераннахром?', fact_ru = 'С 1409 года я взошёл на самаркандский трон и управлял Мавераннахром почти сорок лет. В моё время Самарканд стал научным центром всего Востока.' WHERE id = 39;
UPDATE fact_cards SET topic_ru = 'Обсерватория', question_ru = 'Когда была построена обсерватория Улугбека и каким был её главный инструмент?', fact_ru = 'В 1424–1429 годах я построил в Самарканде огромную обсерваторию. Её главный инструмент — гигантский секстант радиусом около 40 метров. Там мы наблюдали звёзды и составляли точные таблицы.' WHERE id = 40;
UPDATE fact_cards SET topic_ru = '«Зидж-и джадид-и Гурагани»', question_ru = 'Сколько звёзд занесено в каталог «Зидж-и джадид-и Гурагани»?', fact_ru = 'В своём труде «Зидж-и джадид-и Гурагани» я составил точный каталог 1018 звёзд. Веками это сочинение служило пособием по астрономии на Востоке и в Европе.' WHERE id = 41;
UPDATE fact_cards SET topic_ru = 'Длина года', question_ru = 'Насколько точно Мирзо Улугбек вычислил длину года?', fact_ru = 'Длину года я вычислил как 365 дней 6 часов 10 минут 8 секунд — это отличается от современного измерения меньше чем на минуту.' WHERE id = 42;
UPDATE fact_cards SET topic_ru = 'Мои медресе', question_ru = 'В каких городах Мирзо Улугбек построил медресе?', fact_ru = 'Я построил три медресе: в Бухаре (1417), на самаркандском Регистане (1417–1420) и в Гиждуване (1433). На вратах бухарского медресе начертан хадис: «Стремление к знанию — долг каждого мусульманина и мусульманки».' WHERE id = 43;
UPDATE fact_cards SET topic_ru = 'Круг учёных', question_ru = 'Какие учёные собрались вокруг Мирзо Улугбека?', fact_ru = 'Вокруг себя я собрал выдающихся учёных своего времени: моего наставника Казизаде Руми, Гиясиддина Джамшида Каши и моего ученика Али Кушчи.' WHERE id = 44;
UPDATE fact_cards SET topic_ru = 'Кончина', question_ru = 'Чем завершилась жизнь Мирзо Улугбека?', fact_ru = 'Я погиб 27 октября 1449 года в результате заговора моего сына Абдуллатифа. Позже меня похоронили в Гур-Эмире рядом с дедом.' WHERE id = 45;

UPDATE fact_cards SET topic_ru = 'Рождение', question_ru = 'Когда и где родился Алишер Навои?', fact_ru = 'Я родился 9 февраля 1441 года в городе Герат. Моё настоящее имя — Низамиддин Мир Алишер.' WHERE id = 46;
UPDATE fact_cards SET topic_ru = 'Защита родного языка', question_ru = 'Как Алишер Навои защищал тюркский язык?', fact_ru = 'Я великий защитник тюркского (староузбекского) языка. В труде «Спор двух языков» (1499) я доказал, что тюркский язык не уступает персидскому.' WHERE id = 47;
UPDATE fact_cards SET topic_ru = '«Хамса»', question_ru = 'Какие пять поэм входят в «Хамсу» Алишера Навои?', fact_ru = 'В 1483–1485 годах я создал «Хамсу» — пять поэм: «Смятение праведных», «Фархад и Ширин», «Лейли и Меджнун», «Семь планет» и «Стена Искандара».' WHERE id = 48;
UPDATE fact_cards SET topic_ru = 'Государственная служба', question_ru = 'На каких должностях служил Алишер Навои в державе Хусейна Байкары?', fact_ru = 'В державе моего друга Хусейна Байкары я служил сначала хранителем печати (1469), затем визирем (1472). Боролся за справедливость и благополучие народа.' WHERE id = 49;
UPDATE fact_cards SET topic_ru = 'Благотворительность', question_ru = 'Какие сооружения построил Алишер Навои для народа?', fact_ru = 'Свои доходы я тратил на народ: построил около 300 сооружений — медресе, мечети, больницы, бани, мосты и арыки. Медресе «Ихласия» — одно из них.' WHERE id = 50;
UPDATE fact_cards SET topic_ru = 'Мои диваны', question_ru = 'В какие диваны Алишер Навои собрал свои стихи?', fact_ru = 'Свои стихи я собрал в четыре дивана под названием «Хазойин уль-маони» (1491–1498), в них более сорока пяти тысяч строк.' WHERE id = 51;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Под какими псевдонимами писал Алишер Навои?', fact_ru = 'В тюркских стихах я пользовался псевдонимом «Навои» (наво — напев), в персидских — «Фани».' WHERE id = 52;
UPDATE fact_cards SET topic_ru = '«Язык птиц»', question_ru = 'О чём поэма «Язык птиц»?', fact_ru = 'В конце жизни я написал поэму «Язык птиц» (1499) — в ней рассказана повесть о птицах, искавших истину.' WHERE id = 53;
UPDATE fact_cards SET topic_ru = 'Кончина', question_ru = 'Когда и где скончался Алишер Навои?', fact_ru = 'Я скончался 3 января 1501 года в родном городе Герате. Весь город был в трауре.' WHERE id = 54;
UPDATE fact_cards SET topic_ru = 'Дружба с Хусейном Байкарой', question_ru = 'С каким правителем Алишер Навои дружил с детства?', fact_ru = 'С детства я дружил с Хусейном Байкарой — мы вместе учились в школе. Взойдя в 1469 году на хорасанский трон, он призвал меня к себе в Герат.' WHERE id = 1512;
UPDATE fact_cards SET topic_ru = 'Годы учения', question_ru = 'В каких городах учился Алишер Навои?', fact_ru = 'В юности я учился в городах Герат и Мешхед, затем получил образование и в Самарканде. Эти годы поисков знания помогли мне вырасти поэтом и учёным.' WHERE id = 1513;
UPDATE fact_cards SET topic_ru = 'Мой наставник Джами', question_ru = 'Кто был наставником и близким другом Алишера Навои?', fact_ru = 'Великий персидский поэт Абдурахман Джами был моим наставником и близким другом. Его памяти я посвятил труд «Пятерица смятенных».' WHERE id = 1514;
UPDATE fact_cards SET topic_ru = 'Моя тазкира «Собрание утончённых»', question_ru = 'Как называется первая тазкира на тюркском языке, написанная Алишером Навои?', fact_ru = 'В 1491 году я написал тазкиру под названием «Собрание утончённых». Это первая тазкира на тюркском языке, в ней я рассказал более чем о 450 поэтах.' WHERE id = 1515;
UPDATE fact_cards SET topic_ru = '«Возлюбленный сердец»', question_ru = 'Как называется прозаическое сочинение, написанное Алишером Навои в конце жизни?', fact_ru = 'В конце жизни, в 1500 году, я написал сочинение «Возлюбленный сердец». В нём я изложил свои наблюдения о людях разных ремёсел и о добром нраве.' WHERE id = 1516;
UPDATE fact_cards SET topic_ru = 'Любимая книга детства', question_ru = 'Какую поэму Алишер Навои выучил наизусть в детстве?', fact_ru = 'В детстве я очень любил читать поэму Фаридаддина Аттара «Беседа птиц», я даже выучил её наизусть. Эта книга впоследствии сильно повлияла на моё творчество.' WHERE id = 1517;
UPDATE fact_cards SET topic_ru = 'Моё имя живёт', question_ru = 'Какие город и область в Узбекистане названы именем Алишера Навои?', fact_ru = 'Сегодня в Узбекистане моим именем названы область и город — Навои. Государственный театр оперы и балета в Ташкенте тоже носит моё имя.' WHERE id = 1518;
